-- Gerado por scripts/translate_migrations_pg.py a partir de team/migrations/0015_retencao.sql. Nao edite: altere a migracao SQLite e gere de novo.
-- 0015: exclusao controlada de demandas. Os gatilhos "somente de acrescimo" passam a aceitar DELETE apenas
-- dentro de uma transacao que registrou a guarda de exclusao (erasure_guard); UPDATE continua proibido.
CREATE TABLE erasure_guard (token BIGINT PRIMARY KEY CHECK (token = 1));
CREATE TABLE erasure_log (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  tenant_id TEXT NOT NULL REFERENCES tenants(id) DEFERRABLE INITIALLY IMMEDIATE,
  case_id TEXT NOT NULL,
  erased_at TEXT NOT NULL,
  erased_by TEXT NOT NULL,
  counts JSONB NOT NULL
);
CREATE FUNCTION erasure_log_append_only_update_fn() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'o registro de exclusoes e somente de acrescimo' USING ERRCODE = '23000'; RETURN NEW; END $$;
CREATE TRIGGER erasure_log_append_only_update BEFORE UPDATE ON erasure_log FOR EACH ROW EXECUTE FUNCTION erasure_log_append_only_update_fn();
CREATE FUNCTION erasure_log_append_only_delete_fn() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'o registro de exclusoes e somente de acrescimo' USING ERRCODE = '23000'; RETURN OLD; END $$;
CREATE TRIGGER erasure_log_append_only_delete BEFORE DELETE ON erasure_log FOR EACH ROW EXECUTE FUNCTION erasure_log_append_only_delete_fn();
DROP TRIGGER case_entries_append_only_delete ON case_entries;
DROP FUNCTION case_entries_append_only_delete_fn();
CREATE FUNCTION case_entries_append_only_delete_fn() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NOT EXISTS (SELECT 1 FROM erasure_guard) THEN RAISE EXCEPTION 'entradas da demanda sao somente de acrescimo' USING ERRCODE = '23000'; END IF; RETURN OLD; END $$;
CREATE TRIGGER case_entries_append_only_delete BEFORE DELETE ON case_entries FOR EACH ROW EXECUTE FUNCTION case_entries_append_only_delete_fn();
DROP TRIGGER evidences_append_only_delete ON evidences;
DROP FUNCTION evidences_append_only_delete_fn();
CREATE FUNCTION evidences_append_only_delete_fn() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NOT EXISTS (SELECT 1 FROM erasure_guard) THEN RAISE EXCEPTION 'evidencias sao somente de acrescimo; registre uma nova' USING ERRCODE = '23000'; END IF; RETURN OLD; END $$;
CREATE TRIGGER evidences_append_only_delete BEFORE DELETE ON evidences FOR EACH ROW EXECUTE FUNCTION evidences_append_only_delete_fn();
DROP TRIGGER triage_decisions_append_only_delete ON triage_decisions;
DROP FUNCTION triage_decisions_append_only_delete_fn();
CREATE FUNCTION triage_decisions_append_only_delete_fn() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NOT EXISTS (SELECT 1 FROM erasure_guard) THEN RAISE EXCEPTION 'decisoes de triagem sao somente de acrescimo' USING ERRCODE = '23000'; END IF; RETURN OLD; END $$;
CREATE TRIGGER triage_decisions_append_only_delete BEFORE DELETE ON triage_decisions FOR EACH ROW EXECUTE FUNCTION triage_decisions_append_only_delete_fn();
